import fs from 'node:fs';
import assert from 'node:assert/strict';
export const entry=JSON.parse(fs.readFileSync(new URL('fixtures/question-bank-batch2b-before-20261104.json',import.meta.url),'utf8'));
export const version='question-authoring.2026-11-04.batch2b.v1';
const p=s=>'{patientName}, a {ageYears}-year-old {sexNoun}, '+s;
const table=(caption,columns,rows,cells)=>({kind:'table',caption,columnHeaders:columns,rowHeaders:rows,cells});
const none={kind:'no_test'},test=name=>({kind:'test',timingProfileId:'timing.test.'+name});
const construct=(id,name,objective,reason)=>({id:'concept.'+id,name,objective,reason});
const specs=[];
const extraCandidates={B2B41:'question.preoperative-nutrition.nutritional-risk-screening.v2',B2B42:'question.preoperative-nutrition.oral-enteral-first-line.v2'};
for(const[id,variantId]of Object.entries(extraCandidates)){
 const cs=entry.release.cases.find(cs=>cs.decisionNodes.some(n=>n.questionVariantId===variantId));assert(cs,variantId);
 const node=cs.decisionNodes.find(n=>n.questionVariantId===variantId);
 entry.targets.push({id,flagId:null,originalProposalRank:id==='B2B41'?35:36,caseId:cs.id,nodeId:node.id,variantId,conceptId:node.primaryConceptId,cs,node,question:entry.questions[variantId].find(q=>q.answerChoices?.length)});
}
export const deferredItems=entry.targets.filter(t=>['B2B27','B2B28'].includes(t.id)).map(t=>({id:t.id,variantId:t.variantId,conceptId:t.conceptId,disposition:'unchanged_proposed_merge_pending_manager_acceptance',reason:'These generic return-to-individualized-risk-assessment variants duplicate the active-decompensation/timing cases. The locally recorded broad claim does not establish a unique specific treatment/clearance choice. Do not invent an operation threshold or force a generic cautious key; merge/scope decision belongs to the manager.'}));
function add(id,s){const old=entry.targets.find(t=>t.id===id);assert(old,id);specs.push({...old,...s,steps:s.steps,claims:[...new Set([...(s.claims??old.question.supportingEvidenceClaimIds)])]});}

